cpp
IvPFunction* BHV_HoldSpeed::onRunState()
{
  // Step 1: Build ZAIC over the behavior's domain, not just a string
  ZAIC_PEAK zaic(m_domain, "speed");
  zaic.setSummit(m_speed);
  zaic.setPeakWidth(0);
  zaic.setBaseWidth(0.2);
  zaic.setSummitDelta(0);
  zaic.setMinMaxUtil(0, 100);

  // Step 2: Check for configuration errors before extracting
  if(zaic.stateOK() == false) {
    postWMessage("ZAIC_PEAK error: " + zaic.getWarnings());
    return(0);
  }

  // Step 3: Extract and set priority weight before returning
  IvPFunction* ipf = zaic.extractIvPFunction();
  if(ipf)
    ipf->setPWT(m_priority_wt);

  return(ipf);
}

The setPeakWidth, setBaseWidth, etc. calls mirror the BHV_ConstantSpeed defaults and are optional but good practice — leaving them unset means you're relying on whatever the ZAIC defaults happen to be, which makes the function shape fragile if defaults ever change.

